/** The demo knowledge model (generated by scripts/build_corpus.py) and the in-browser reasoning over it. */
import raw from './corpus.json'

export type Step = { step: string; at: string; detail: string }
export type Artifact = {
  id: string; type: 'pdf' | 'docx'; title: string; short: string; date: string; kind: string; project: string; authors: string[]
  summary: string; file: string; size_bytes: number; sha256: string; pages: number | null; concepts: string[]; entities: string[]
  fragment_count: number; pipeline: Step[]
}
export type Fragment = { id: string; artifact_id: string; section: string; text: string; location: { page?: number; paragraph?: number }; concepts: string[]; entities: string[] }
export type Link = { source: string; target: string; type: string; origin: 'authored' | 'semantic'; evidence?: string; score?: number; shared?: string[] }
export type Concept = { name: string; artifacts: string[]; fragments: number }
export type Entity = { name: string; kind: string; artifacts: string[] }

const data = raw as unknown as { owner: string; note: string; artifacts: Artifact[]; fragments: Fragment[]; links: Link[]; concepts: Concept[]; entities: Entity[] }
export const { owner: OWNER, artifacts: ARTIFACTS, fragments: FRAGMENTS, links: LINKS, concepts: CONCEPTS, entities: ENTITIES } = data

export const artifact = (id: string) => ARTIFACTS.find(a => a.id === id)!
export const fragment = (id: string) => FRAGMENTS.find(f => f.id === id)!
export const fragmentsOf = (id: string) => FRAGMENTS.filter(f => f.artifact_id === id)
export const linksOf = (id: string) => LINKS.filter(l => l.source === id || l.target === id)
export const degree = (id: string) => linksOf(id).length
export const where = (f: Fragment) => (f.location.page ? `p. ${f.location.page}` : `¶ ${f.location.paragraph}`)
export const PROJECTS = ['CEREBRO', 'MealSenseAI', 'Coursework', 'Infrastructure'] as const
export const PROJECT_COLOR: Record<string, string> = { CEREBRO: '#2a5d9f', MealSenseAI: '#0f766e', Coursework: '#9a5b13', Infrastructure: '#6b4fa0' }
export const fmtDate = (d: string) => new Date(d + 'T00:00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })

/** Relationship as read from one document's side: "extends → X" or "← extended by X". */
export function relationFrom(l: Link, id: string) {
  const out = l.source === id
  return { other: out ? l.target : l.source, label: l.origin === 'semantic' ? 'similar to' : out ? l.type : `← ${l.type}`, out }
}

// ---------- Recall: BM25 over fragments, with a small boost for concepts named in the question ----------
const STOP = new Set('a an and are as at be by do does for from has have how i in into is it its me my of on or our so that the their this to was were what when where which who why will with can'.split(' '))
export const tokenize = (s: string) => (s.toLowerCase().match(/[a-z0-9][a-z0-9-]+/g) ?? []).filter(w => !STOP.has(w) && w.length > 1)
const stem = (w: string) => w.replace(/(ies|es|s|ing|ed)$/, '')
const docs = FRAGMENTS.map(f => tokenize(`${f.text} ${f.section} ${artifact(f.artifact_id).title}`).map(stem))
const avg = docs.reduce((n, d) => n + d.length, 0) / docs.length
const df = new Map<string, number>()
docs.forEach(d => new Set(d).forEach(w => df.set(w, (df.get(w) ?? 0) + 1)))

// Query expansion: a few domain synonyms, so "How accurate…" also finds "accuracy" and "top-1". Expanded terms count 70%.
const EXPAND: Record<string, string[]> = {
  accurate: ['accuracy', 'top-1', 'macro-f1'], dataset: ['food-101', 'foodsg-233', 'trained'], run: ['host', 'server', 'deploy'],
  evaluat: ['benchmark', 'measur', 'ground'], why: ['decision', 'agreed'], insulin: ['medication', 'dosing'], store: ['postgresql', 'database'],
}

export type Hit = { f: Fragment; score: number; terms: string[] }
export function search(q: string, k = 6): Hit[] {
  const asked = [...new Set(tokenize(q).map(stem))]
  if (!asked.length) return []
  const extra = new Set(asked.flatMap(t => EXPAND[t] ?? []).map(stem).filter(t => !asked.includes(t)))
  const terms = [...asked, ...extra]
  const named = CONCEPTS.filter(c => tokenize(c.name).map(stem).some(t => asked.includes(t))).map(c => c.name)
  const hits = FRAGMENTS.map((f, i) => {
    const d = docs[i]; let s = 0; const matched: string[] = []
    for (const t of terms) {
      const tf = d.filter(w => w === t || (extra.has(t) && w.startsWith(t))).length
      if (!tf) continue
      matched.push(t)
      const idf = Math.log(1 + (docs.length - (df.get(t) ?? 0) + 0.5) / ((df.get(t) ?? 0) + 0.5))
      s += (extra.has(t) ? 0.7 : 1) * idf * (tf * 2.2) / (tf + 1.2 * (0.25 + 0.75 * d.length / avg))
    }
    s += 0.6 * f.concepts.filter(c => named.includes(c)).length
    if (f.section === 'Summary') s *= 0.8
    return { f, score: s, terms: matched }
  }).filter(h => h.score > 0.5).sort((a, b) => b.score - a.score)
  const out: Hit[] = []; const per = new Map<string, number>()
  for (const h of hits) {   // at most two passages per document, so answers draw on several sources
    const n = per.get(h.f.artifact_id) ?? 0
    if (n < 2) { out.push(h); per.set(h.f.artifact_id, n + 1) }
    if (out.length >= k) break
  }
  return out
}

/** Authored links among the documents an answer cites: the "reasoning trail" between its sources. */
export const trail = (ids: string[]) => LINKS.filter(l => l.origin === 'authored' && ids.includes(l.source) && ids.includes(l.target))
